<section class="vc-card mt-3"><div class="vc-card-head"><h2>Emergency controls</h2></div><div class="vc-card-body"><div class="vc-callout danger">Use emergency actions only for account compromise, customer-data exposure, serious delivery incidents, or immediate operational risk. Every action will require backend confirmation and an audit reason.</div><div class="vc-actions mt-3"><button type="button" class="vc-btn danger" data-demo-action="Report account compromise">Account compromise</button><button type="button" class="vc-btn danger" data-demo-action="Report data incident">Data incident</button><button type="button" class="vc-btn danger" data-demo-action="Stop new orders">Temporarily stop orders</button></div></div></section>
<dialog class="vc-dialog" id="ticket-dialog"><div class="vc-dialog-head"><h2>Raise support ticket</h2><button type="button" class="vc-btn small" data-close-dialog>Close</button></div><form class="vc-dialog-body" data-frontend-form="ticket" data-success="Ticket validated and queued for backend connection."><div class="vc-form-grid"><div class="vc-field"><label for="vc-support-select-2">Category</label><select name="vc-support-select-2" id="vc-support-select-2" class="vc-select" required><option value="">Select</option><option>Order</option><option>Delivery</option><option>Return/refund</option><option>Payout</option><option>Product approval</option><option>Account/KYC</option><option>Event</option><option>Technical</option></select></div><div class="vc-field"><label for="vc-support-input-3">Related reference</label><input name="vc-support-input-3" id="vc-support-input-3" class="vc-input" maxlength="60" placeholder="Order, payout, product, or event ID"></div><div class="vc-field full"><label for="vc-support-input-4">Subject</label><input name="vc-support-input-4" id="vc-support-input-4" class="vc-input" required minlength="8" maxlength="120"></div><div class="vc-field full"><label for="vc-support-textarea-5">Description</label><textarea name="vc-support-textarea-5" id="vc-support-textarea-5" class="vc-textarea" required minlength="30" maxlength="3000"></textarea></div><div class="vc-field full"><label for="vc-support-input-6">Attachment</label><input name="vc-support-input-6" id="vc-support-input-6" class="vc-input" type="file" accept="image/jpeg,image/png,application/pdf" data-max-bytes="5242880"></div></div><div class="vc-form-actions"><button class="vc-btn primary" type="submit">Validate ticket</button></div></form></dialog>
